{"ideviceId":"idevice-1781086148712-kg10udkf0","lomloeDataset":"ES-EFP","lomloeActiveTab":"saberes","lomloeSelectedEtapa":"ESO","lomloeSelectedNivel":"3º ESO","lomloeSelectedMateria":{"codArea":"FQX","denominacion":"Physics and Chemistry"},"lomloeSelections":[{"id":"criterioESO3º ESOFQXES-EFP-ESO3-FQX-CE01ES-EFP-ESO3-FQX-CE01-CR01","type":"criterio","dataset":"ES-EFP","etapa":"ESO","nivel":"3º ESO","codArea":"FQX","denominacion":"Physics and Chemistry","codigoComp":"ES-EFP-ESO3-FQX-CE01","descripcionComp":"Understand and relate the reasons why the main physical and chemical phenomena in the environment occur, explaining them through appropriate scientific laws and theories to solve problems and apply them to improving the immediate environment and human quality of life.","codigoCriterio":"ES-EFP-ESO3-FQX-CE01-CR01","descripcionCriterio":"Identify, understand and explain the most relevant everyday physical and chemical phenomena using appropriate scientific principles, theories and laws, presenting reasoned explanations through a variety of formats and communication media.","competenciasClave":["CCL1","STEM1","STEM2","STEM4"],"partial":false,"descriptorOptions":["CCL1","STEM1","STEM2","STEM4","CPSAA4"]},{"id":"criterioESO3º ESOFQXES-EFP-ESO3-FQX-CE01ES-EFP-ESO3-FQX-CE01-CR02","type":"criterio","dataset":"ES-EFP","etapa":"ESO","nivel":"3º ESO","codArea":"FQX","denominacion":"Physics and Chemistry","codigoComp":"ES-EFP-ESO3-FQX-CE01","descripcionComp":"Understand and relate the reasons why the main physical and chemical phenomena in the environment occur, explaining them through appropriate scientific laws and theories to solve problems and apply them to improving the immediate environment and human quality of life.","codigoCriterio":"ES-EFP-ESO3-FQX-CE01-CR02","descripcionCriterio":"Solve the physical and chemical problems posed using appropriate scientific laws and theories, explaining the reasoning behind the procedures used to find solutions and expressing the results appropriately.","competenciasClave":["CCL1","STEM1","STEM2"],"partial":false,"descriptorOptions":["CCL1","STEM1","STEM2","STEM4","CPSAA4"]},{"id":"criterioESO3º ESOFQXES-EFP-ESO3-FQX-CE01ES-EFP-ESO3-FQX-CE01-CR03","type":"criterio","dataset":"ES-EFP","etapa":"ESO","nivel":"3º ESO","codArea":"FQX","denominacion":"Physics and Chemistry","codigoComp":"ES-EFP-ESO3-FQX-CE01","descripcionComp":"Understand and relate the reasons why the main physical and chemical phenomena in the environment occur, explaining them through appropriate scientific laws and theories to solve problems and apply them to improving the immediate environment and human quality of life.","codigoCriterio":"ES-EFP-ESO3-FQX-CE01-CR03","descripcionCriterio":"Recognise and describe real scientific problems in the immediate environment and undertake initiatives in which science, particularly physics and chemistry, can contribute to solving them, critically analysing their impact on society.","competenciasClave":["CCL1","STEM1","STEM2","CPSAA4"],"partial":false,"descriptorOptions":["CCL1","STEM1","STEM2","STEM4","CPSAA4"]},{"id":"criterioESO3º ESOFQXES-EFP-ESO3-FQX-CE02ES-EFP-ESO3-FQX-CE02-CR01","type":"criterio","dataset":"ES-EFP","etapa":"ESO","nivel":"3º ESO","codArea":"FQX","denominacion":"Physics and Chemistry","codigoComp":"ES-EFP-ESO3-FQX-CE02","descripcionComp":"Express students’ observations as questions, formulate hypotheses to explain them, and demonstrate these hypotheses through scientific experimentation, inquiry and evidence-gathering, to develop scientific reasoning and improve skills in using scientific methods.","codigoCriterio":"ES-EFP-ESO3-FQX-CE02-CR01","descripcionCriterio":"Use scientific methods to identify and describe phenomena based on questions that can be answered through inquiry, deduction, experimental work and logical and mathematical reasoning, distinguishing them from pseudoscientific questions that cannot be tested experimentally.","competenciasClave":["CCL1","CCL3","STEM1"],"partial":false,"descriptorOptions":["CCL1","CCL3","STEM1","STEM2","CD1","CPSAA4","CE1","CCEC3"]},{"id":"criterioESO3º ESOFQXES-EFP-ESO3-FQX-CE02ES-EFP-ESO3-FQX-CE02-CR02","type":"criterio","dataset":"ES-EFP","etapa":"ESO","nivel":"3º ESO","codArea":"FQX","denominacion":"Physics and Chemistry","codigoComp":"ES-EFP-ESO3-FQX-CE02","descripcionComp":"Express students’ observations as questions, formulate hypotheses to explain them, and demonstrate these hypotheses through scientific experimentation, inquiry and evidence-gathering, to develop scientific reasoning and improve skills in using scientific methods.","codigoCriterio":"ES-EFP-ESO3-FQX-CE02-CR02","descripcionCriterio":"According to the nature of the questions being addressed, select the best way to test or refute the proposed hypotheses, designing inquiry and evidence-gathering strategies that produce conclusions and answers appropriate to the question asked.","competenciasClave":["CCL1","CCL3","STEM1","STEM2","CD1","CPSAA4"],"partial":false,"descriptorOptions":["CCL1","CCL3","STEM1","STEM2","CD1","CPSAA4","CE1","CCEC3"]},{"id":"saberESO3º ESOFQXA. Las destrezas científicas básicasES-EFP-ESO3-FQX-SB01-001","type":"saber","dataset":"ES-EFP","etapa":"ESO","nivel":"3º ESO","codArea":"FQX","denominacion":"Physics and Chemistry","bloque":"A. Basic scientific skills","nombre":"ES-EFP-ESO3-FQX-SB01-001","subtitulo1":"Scientific research methods: identifying and formulating questions, developing hypotheses and testing them experimentally.","subtitulo2":""},{"id":"saberESO3º ESOFQXA. Las destrezas científicas básicasES-EFP-ESO3-FQX-SB01-002","type":"saber","dataset":"ES-EFP","etapa":"ESO","nivel":"3º ESO","codArea":"FQX","denominacion":"Physics and Chemistry","bloque":"A. Basic scientific skills","nombre":"ES-EFP-ESO3-FQX-SB01-002","subtitulo1":"Experimental work and research projects: strategies for solving problems and conducting research through inquiry, deduction, evidence-gathering and logical and mathematical reasoning, making valid inferences from observations and drawing conclusions.","subtitulo2":""},{"id":"saberESO3º ESOFQXA. Las destrezas científicas básicasES-EFP-ESO3-FQX-SB01-003","type":"saber","dataset":"ES-EFP","etapa":"ESO","nivel":"3º ESO","codArea":"FQX","denominacion":"Physics and Chemistry","bloque":"A. Basic scientific skills","nombre":"ES-EFP-ESO3-FQX-SB01-003","subtitulo1":"Different scientific learning environments and resources, such as laboratories and virtual environments: materials, substances and technological tools.","subtitulo2":""}],"lomloeSummaryHtml":"<h3 class="lomloe-export-title">LOMLOE Curriculum Alignment</h3><p class="lomloe-export-meta">Curriculum alignment: <strong>LOMLOE — MEFPD administrative area</strong>  | Selected elements: <strong>8</strong> (5 assessment criteria, 3 core knowledge items)</p><table class="lomloe-export-table"><thead><tr><th data-lomloe-tip="Specific competences">Specific competence</th><th data-lomloe-tip="Assessment criteria">Assessment criteria</th><th data-lomloe-tip="Operational descriptors">Operational descriptors</th><th>Core knowledge</th></tr></thead><tbody><tr><td rowspan="3"><strong data-lomloe-tip="ESO · 3rd year of ESO · Physics and Chemistry

